class Solution:
    def two_sum(self, nums: list[int], target: int) -> list[int]:
        n = len(nums)

        # A pair requires two different indices.
        if n < 2:
            return []

        # Check every pair once by keeping
        # the second index ahead of the first.
        for first in range(n - 1):
            for second in range(first + 1, n):
                current_sum = nums[first] + nums[second]

                # The current pair gives the required sum.
                if current_sum == target:
                    return [first, second]

        # No valid pair exists.
        return []


if __name__ == "__main__":
    nums = [2, 7, 11, 15]
    target = 9

    solution = Solution()
    answer = solution.two_sum(nums, target)

    print(*answer)

